	// transformed algorithm. Each iteration fixes a source row k in both
	// A (row index) and B (row B[k][*]).
	traverser(A).template for_dims<'i'>([&](auto trav_i_full) {
		// trav_i_full has dimension 'i' fixed; 'k' remains free.
		auto row_state = trav_i_full.state();
		const std::size_t row_k = get_index<'i'>(row_state); // this is k

