		// B_row_k has only dimension 'j'.
		auto B_row_k = B ^ fix<'i'>(row_k);

		// We need all columns i with i < k. We achieve this by slicing the
		// 'k' dimension of A's column index range to [0, k).
		//
		//   into: columns: 0, 1, ..., k-1
		//
		// This corresponds to the inner loop "for (i = 0; i < k; ++i)".
		auto trav_k_range = trav_i_full.order(slice<'k'>(0, row_k));

		// Now iterate these columns (dimension 'k' in A, corresponding to i
		// in the mathematical formulation).
		trav_k_range.template for_dims<'k'>([&](auto trav_ik) {
			// trav_ik has both 'i' (row_k) and 'k' (col_i) fixed.
			auto ik_state = trav_ik.state();
			const std::size_t col_i = get_index<'k'>(ik_state); // this is i

			// A_ki = A[k][i]  (A has dimensions 'i' x 'k')
			const num_t A_ki = A[ik_state];

			// Destination row view B[i][j]; only dimension 'j' remains.
			auto B_row_i = B ^ fix<'i'>(col_i);

			// Innermost loop over 'j' for both B[i][j] and B[k][j].
			// Using a joint traverser ensures both rows are stepped over
			// in lockstep and that 'j' is the single (and hence innermost)
			// dimension.
			traverser(B_row_i, B_row_k).for_each([&](auto s_j) {
				// s_j contains only index 'j'.
				num_t &Bij = B_row_i[s_j];     // B[i][j]
				const num_t Bkj = B_row_k[s_j]; // B[k][j], source row

				Bij += A_ki * Bkj;
			});
		});
	});

