	using namespace noarr;

	const std::size_t m_len = A | get_length<'i'>();

	// A small 1D structure used only to drive the k-loop:
	//   dimension 'k' ranges from 0 to m_len-1.
	// No data are attached to this structure; it is purely an index generator.
	auto k_structure = noarr::scalar<char>() ^ k_vec ^ noarr::set_length<'k'>(m_len);
	auto base_k_traverser = noarr::traverser(k_structure);

	#pragma scop
	// Default traverser(B).for_each traverses dimensions in their signature order.
	// For B: 'j' is outer and 'i' is inner, which matches its column-major layout
	// (i is the contiguous dimension). This improves cache locality for B[i][j].
	traverser(B).for_each([&](auto state_ij) {
		auto [i, j] = get_indices<'i', 'j'>(state_ij);
		const std::size_t i_idx = static_cast<std::size_t>(i);

		num_t Bij = B[state_ij];

		// k-loop: for (k = i+1; k < M; k++)
		if (i_idx + 1 < m_len) {
			const std::size_t k_start = i_idx + 1;
			const std::size_t k_count = m_len - k_start;

			// Restrict the 1D k-structure to [k_start, m_len) using a slice.
			// The state passed to the inner lambda already contains the original
			// k indices (no need to add k_start manually).
			base_k_traverser
				.order(noarr::slice<'k'>(k_start, k_count))
				.for_each([&](auto state_k) {
					auto k = get_index<'k'>(state_k);

					// A[k][i] -> A at (i = k, k = i)
					auto a_state = noarr::idx<'i', 'k'>(k, i);
					// B[k][j] -> B at (i = k, j = j)
					auto bkj_state = noarr::idx<'i', 'j'>(k, j);

					Bij += A[a_state] * B[bkj_state];
				});
		}

		Bij *= alpha;
		B[state_ij] = Bij;
	});
	#pragma endscop
}

