		// For kk > ii we leave A[state] uninitialized, matching the C code
	});

	// Initialize B
	// for (i = 0; i < m; i++)
	//   for (j = 0; j < n; j++)
	//     B[i][j] = ((n + (i - j)) % n) / n;
	traverser(B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		int ii = static_cast<int>(i);
		int jj = static_cast<int>(j);

		B[state] = (num_t)(((n_len + (ii - jj)) % n_len)) / (num_t)n_len;
	});
}

// Main computational kernel
// Original C:
//
// for (i = 0; i < _PB_M; i++)
//   for (j = 0; j < _PB_N; j++) {
//     for (k = i+1; k < _PB_M; k++)
//       B[i][j] += A[k][i] * B[k][j];
//     B[i][j] = alpha * B[i][j];
//   }
//
// A is MxM (i x k), B is MxN (i x j)
//
// Optimized Noarr version:
//
// - The outer (i,j) loops are expressed via traversers over B.
// - The inner k-loop is expressed as a traverser over *views* of A and B
//   that represent the ranges k = i+1 .. M-1, created with `fix` + `shift`.
// - For each fixed (i,j):
//     A_tail_i(k)  ~ A[k][i]   for k > i
//     B_tail_ij(k) ~ B[k][j]   for k > i
//   so that the k-loop becomes a clean Noarr traversal over the shared
//   dimension (here still named 'i' in the views).
[[gnu::flatten, gnu::noinline]]
void kernel_trmm(num_t alpha, auto A, auto B) {
	using namespace noarr;

	#pragma scop
	// Outer loop over rows `i` of B (and columns of A).
	traverser(B).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed, iterates over the remaining dimension(s) of B (here 'j').

		// Extract the current row index i once per row.
		const auto state_i = trav_i.state();
		const std::size_t i = get_index<'i'>(state_i);

		// View of the i-th "column" of A:
		// - Original A has dimensions 'i' and 'k'.
		// - We fix 'k' to i, leaving only the 'i' dimension, which now plays the role of k.
		auto A_col_i = A ^ fix<'k'>(i);

		// Tail of that column starting at k = i + 1.
		// This matches the loop range `for (k = i+1; k < M; ++k)`.
		auto A_tail_i = A_col_i ^ shift<'i'>(i + 1);

		// Inner loop over columns `j` for the current row `i`.
		trav_i.for_each([&](auto state_ij) {
			// state_ij carries both 'i' and 'j'; 'i' is fixed for this trav_i.
			const std::size_t j = get_index<'j'>(state_ij);

			// Load B[i][j] into a scalar accumulator.
			num_t Bij = B[state_ij];

			// View of the j-th column of B:
			// - Fix 'j' to the current column, leaving the 'i' dimension
			//   which indexes rows (k in the original notation).
			auto B_col_j = B ^ fix<'j'>(j);

			// Tail of that column starting at k = i + 1.
			auto B_tail_ij = B_col_j ^ shift<'i'>(i + 1);

			// k-loop: traverse in lockstep over A_tail_i and B_tail_ij
			// along their shared 'i' dimension (which encodes k > i).
			traverser(A_tail_i, B_tail_ij).for_each([&](auto state_k) {
				// Each state_k corresponds to some k in {i+1, ..., M-1}.
				// Due to the `shift`, both views map this state to the
				// correct original indices:
				//   A_tail_i[state_k]  -> A[k][i]
				//   B_tail_ij[state_k] -> B[k][j]
				Bij += A_tail_i[state_k] * B_tail_ij[state_k];
			});

			// Post-scale by alpha and write back B[i][j].
			Bij *= alpha;
			B[state_ij] = Bij;
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;

	// set lengths for all dimensions used
	auto set_lengths = noarr::set_length<'i'>(m)
	                 ^ noarr::set_length<'j'>(n)
	                 ^ noarr::set_length<'k'>(m);

	// allocate bags
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths); // M x M
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths); // M x N

	// initialize data
	init_array(alpha, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_trmm(alpha, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (for DCE prevention / correctness check)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, B.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
